$(document).ready(function () {
    // 桌面端侧边栏高度与滚动监听
    if ($(window).width() >= 768) {
        var wrapper_height = $(".navbar-nav").outerHeight();
        $("#content-wrapper").css("min-height", wrapper_height + "px");

        setInterval(function () {
            if ($('#accordionSidebar').outerHeight() > $(window).height()) {
                $('#accordionSidebar').css('height', '100vh').css('overflow-x', 'hidden');
            }
        }, 300);
    }

    /**
     * 移动端抽屉式侧滑菜单切换函数
     * @param {boolean} [show] 显式指定打开或关闭状态，未传则切换
     */
    function toggleMobileSidebar(show) {
        var $sidebar = $(".sidebar");
        var $backdrop = $("#sidebarBackdrop");

        if (!$backdrop.length) {
            $backdrop = $('<div id="sidebarBackdrop" class="sidebar-backdrop"></div>').appendTo('body');
            $backdrop.on('click', function () {
                toggleMobileSidebar(false);
            });
        }

        if (show === undefined) {
            show = !$sidebar.hasClass("show-sidebar");
        }

        if (show) {
            $sidebar.addClass("show-sidebar");
            $backdrop.addClass("show");
            $('body').addClass('sidebar-open');
        } else {
            $sidebar.removeClass("show-sidebar");
            $backdrop.removeClass("show");
            $('body').removeClass('sidebar-open');
        }
    }

    // 绑定移动端顶部汉堡按钮切换侧边栏
    $("#sidebarToggleTop").on('click', function (e) {
        e.preventDefault();
        toggleMobileSidebar();
    });

    // 窗口尺寸重置时自动清理移动端抽屉状态
    $(window).on('resize', function () {
        if ($(window).width() >= 768) {
            $(".sidebar").removeClass("show-sidebar");
            $("#sidebarBackdrop").removeClass("show");
            $('body').removeClass('sidebar-open');
        }
    });
});
  
